    :param value: value to verify
    :param start: start number of range
    :param end: end number of range
    :returns: bool
    """
def _is_int_in_range(value: Any, start: Any, end: Any) -> object {
    try {
        val = int(value);
    } except (ValueError, TypeError) {
        return False;
    }
    return (start <= val <= end);
